head.script:
scwin.getType = function(info) {
    //debugger;
    var rowIndex = info.rowIndex;
    var colIndex = info.colIndex;
    var returnInfo;
    var inputType = inputTypeList.getCellData(rowIndex, colIndex);
    switch (inputType) {
        case "select1":
            returnInfo = {
                id: "dynamic_select1_" + rowIndex + "_" + colIndex,
                inputType: "select",
                options: {
                    viewType: "icon"
                },
                itemSet: {
                    nodeset: "data:dataList4",
                    label: "col1",
                    value: "col2"
                }
            }
            break;
        case "select2":
            returnInfo = {
                id: "dynamic_select2_" + rowIndex + "_" + colIndex,
                inputType: "select",
                options: {
                    viewType: "icon"
                },
                itemSet: {
                    nodeset: "data:dataList5",
                    label: "col1",
                    value: "col2"
                }
            }
            break;
        case "autoComplete":
            returnInfo = {
                id: "dynamic_autoComplete_" + rowIndex + "_" + colIndex,
                inputType: "autoComplete",
                options: {
                    viewType: "icon"
                },
                itemSet: {
                    nodeset: "data:dataList3",
                    label: "label",
                    value: "value"
                }
            }
            break;
        case "checkcombobox":
            returnInfo = {
                id: "dynamic_checkcombobox_" + rowIndex + "_" + colIndex,
                inputType: "checkcombobox",
                options: {
                    viewType: "icon"
                },
                itemSet: {
                    nodeset: "data:dataList3",
                    label: "label",
                    value: "value"
                }
            }
            break;
    }
    if (returnInfo) {
        console.log("[typeGetter] (" + rowIndex + ", " + colIndex + ") : " + returnInfo.inputType);
    }
    return returnInfo;
}
scwin.inputTypeList_oncelldatachange = function(info) {
    //debugger;
};
scwin.gridView1_onviewchange = function(info) {
    var rowIndex = info.rowIndex;
    var colIndex = 2;
    var inputType = info.newValue;
    inputTypeList.setCellData(rowIndex, colIndex, inputType);
    gridView1.refreshCell(rowIndex, colIndex);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_0_1').attr(dataInputtype) == 'select'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
    window.dataArr = [
        "select1", "select1",
        "select2", "select2",
        "autoComplete", "autoComplete",
        "checkcombobox", "checkcombobox"
    ];
    dataList2.setData(dataArr);
    dataList3.setData(dataArr);
    window._dataArr = [];
    for (var i = 0; i < 30; i++) {
        _dataArr.push("");
    }
    dataList1.setData(_dataArr.slice(0));
    inputTypeList.setData(_dataArr.slice(0));
    window.dataInputtype = WebSquare.util.getDataPrefix("inputtype");
}
